function applyDelta(view, delta) {
  // view: Map<viewKey, number>; delta: {tenantId, viewId, valueDelta}
  const key = delta.tenantId + ':' + delta.viewId;
  view[key] = (view[key] || 0) + delta.valueDelta;
  return view;
}
```

