function authorize(input, policyStore) {
  const policy = policyStore.get(input.tenant_id);
  if (!policy.allows(input.role, input.data_class)) {
    throw new AccessDeniedError(`Access denied for tenant ${input.tenant_id}`);
  }
  return { allowed: true, auditId: generateAuditId() };
